/**
 * @suppress
 */
public object FfiConverterTypeLorepiaCore: FfiConverter<LorepiaCore, Pointer> {

    override fun lower(value: LorepiaCore): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): LorepiaCore {
        return LorepiaCore(value)
    }

    override fun read(buf: ByteBuffer): LorepiaCore {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LorepiaCore) = 8UL

    override fun write(value: LorepiaCore, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



